import yfinance as yf
import pandas as pd
import numpy as np

tickers = ['^GSPC', 'GC=F', 'CL=F', '^TNX', 'DX-Y.NYB']
periods = [
    ('2023-10-06', '2023-11-07'),
    ('2024-04-12', '2024-05-13')
]

results = {}

for start_date, end_date in periods:
    period_results = {}
    for ticker in tickers:
        data = yf.download(ticker, start=start_date, end=end_date)
        if not data.empty:
            returns = data['Adj Close'].pct_change().dropna()
            total_return = (data['Adj Close'].iloc[-1] / data['Adj Close'].iloc[0]) - 1
            volatility = returns.std() * np.sqrt(252)
            period_results[ticker] = {
                'return': float(total_return),
                'volatility': float(volatility)
            }
    results[f"{start_date}_{end_date}"] = period_results

print(results)

